Lemma rticks_ok_new_region : ticks_ok st -> ticks_ok st'.
Proof. try hcb. try hsb. intros H. exact H. Qed.

Lemma rptrs_in_new_region (P : N -> Prop) : ptrs_in P st -> ptrs_in P st'.
Proof. ltac2:(KReplay.runh [|@P|] [|constr:(@Corelib.Numbers.BinNums.N); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.HeapCeil.hceil_range); constr:(HCEIL); constr:(@Corelib.Init.Logic.and); constr:(@Stdlib.ZArith.BinInt.Z.le); constr:(@Corelib.Numbers.BinNums.Zpos); constr:(@Corelib.Numbers.BinNums.xO); constr:(@Corelib.Numbers.BinNums.xI); constr:(@Corelib.Numbers.BinNums.xH); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.HeapCeil.hceil); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.HeapSecret.hsecret_range); constr:(HSEC); constr:(@Corelib.Numbers.BinNums.Z0); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.HeapSecret.hsecret); constr:(@Stdlib.ZArith.BinInt.Z.lt); constr:(@Stdlib.ZArith.BinInt.Z.pow); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.HeapSecret.hcanary_range); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.HeapSecret.hcanary); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Agent.MallocTree.ptrs_in); constr:(st)|] [|@H; @HCANB; @HSECB; @HCEILB; @P|] "#$9#'#:#5#,#2#6#8#*#'#+#3#4#7#9#:#;#<#&#=###0#1#/#.#-(#5$#6$#7$#8%#9%k##HIUJD$E$#$#$#$#$#$#$#$#$#$#$#$#$###$#$#$#$#$#$#$#$###############################################%#UKD&$#$s#&$#$#$#$#$#$#$#$###############################################%#&s#%#'s#%#m#s#W#ULCUMC&F##E%##$########%#VN)#VG-#'-#m#0#UOCUPC&F#VG$)'$#m#'#VQRS#j#$#S$l#%%&#l#&,-#l#'<=#j#(s#s##"). Qed.
End NEWREGION.

